from itertools import combinations


def transform(grid):
    height, width = len(grid), len(grid[0])
    occupied = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    tiles = []
    for r in range(height - 1):
        for c in range(width - 1):
            window = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            cells = window & occupied
            if len(cells) == 4:
                tiles.append((cells, 1, None))
            for triple in combinations(sorted(cells), 3):
                missing = next(iter(window - set(triple)))
                color = {(r, c): 2, (r + 1, c): 3, (r, c + 1): 4, (r + 1, c + 1): 5}[missing]
                tiles.append((set(triple), color, missing))

    solutions = []
    def cover(remaining, chosen):
        if not remaining:
            solutions.append(chosen)
            return
        cell = min(remaining)
        for tile in tiles:
            cells = tile[0]
            if cell in cells and cells <= remaining:
                cover(remaining - cells, chosen + [tile])
    cover(occupied, [])
    chosen = solutions[0]
    output = [[0 for _ in row] for row in grid]
    for cells, color, missing in chosen:
        for r, c in cells:
            output[r][c] = color
    return output
